def arr(xs): return '['+','.join('"'+x.replace('\\','\\\\').replace('"','\\"')+'"' for x in xs)+']'
def objkey(k): return k if k.isidentifier() else '"'+k+'"'
def q(s): return '"'+s.replace('\\','\\\\').replace('"','\\"')+'"'

def build(b):
    key=b['name'].lower().replace(' ','-')
    st='['+','.join('{title:'+q(a)+',chapters:'+q(c)+',description:'+q(d)+'}' for a,c,d in b['structure'])+']'
    ch='['+','.join('['+q(a)+','+q(d)+']' for a,d in b['chapters'])+']'
    return f'''  {key}: {{\n    slug:{q(key)}, name:{q(b['name'])}, subtitle:{q(b['subtitle'])}, genre:{q(b['genre'])}, setting:{q(b['setting'])}, authorship:{q(b['authorship'])}, dating:{q(b['dating'])},\n    overview:{q(b['overview'])},\n    structure:{st},\n    majorPeople:{arr(b['people'])}, majorPlaces:{arr(b['places'])}, majorThemes:{arr(b['themes'])},\n    historicalQuestions:{arr(b['questions'])},\n    canon:{{protestant:{q('Canonical New Testament book.')},catholic:{q('Canonical New Testament book.')},eastern-orthodox:{q('Canonical New Testament book in Orthodox tradition.')},ethiopian-orthodox:{q('Canonical scripture within the Ethiopian tradition.')}}},\n    studyNotes:{arr(b['notes'])},\n    chapters: buildChapters({q(b['name'])},{ch},{len(b['chapters'])},n=>n<={len(b['chapters'])//5 or 1}?"Early Ministry":n<={len(b['chapters'])*2//5 or 1}?"Public Ministry":n<={len(b['chapters'])*3//5 or 1}?"Teaching and Conflict":n<={len(b['chapters'])*4//5 or 1}?"Jerusalem and Passion":"Passion and Resurrection",{arr(b['questions'])},{arr(b['themes'][:4])})\n  }},\n'''

# fix hyphen canon keys by quoting, and add entries
entries=''.join(build(b) for b in books.values())
# build output has invalid hyphen keys in canon; quote them globally only in generated segment
entries=entries.replace('eastern-orthodox:', '"eastern-orthodox":').replace('ethiopian-orthodox:', '"ethiopian-orthodox":')
s=s[:insert_at]+ '\n'+entries + s[insert_at:]
p.write_text(s)
